t.script:
document.addEventListener('DOMContentLoaded', function() {
    const addReceiptBtn = document.getElementById('addReceiptBtn');
    const receiptInput = document.getElementById('receiptInput');
    const receiptsList = document.getElementById('receiptsList');
    const form = document.getElementById('expenseForm');
    let selectedReceipts = [];

    // Receipt handling functions
    addReceiptBtn.addEventListener('click', function() {
        receiptInput.click();
    });

    receiptInput.addEventListener('change', function(e) {
        const files = Array.from(e.target.files);

        files.forEach(file => {
            // Check file size (10MB)
            const maxSize = 10 * 1024 * 1024;
            if (file.size > maxSize) {
                alert(`File "${file.name}" exceeds 10MB limit and will not be added.`);
                return;
            }

            // Check if file already added
            const isDuplicate = selectedReceipts.some(f =>
                f.name === file.name && f.size === file.size
            );

            if (!isDuplicate) {
                selectedReceipts.push(file);
            }
        });

        renderReceiptsList();
        receiptInput.value = ''; // Reset file input
    });

    function renderReceiptsList() {
        receiptsList.innerHTML = '';

        if (selectedReceipts.length === 0) {
            return;
        }

        const listGroup = document.createElement('div');
        listGroup.className = 'list-group mb-2';

        selectedReceipts.forEach((file, index) => {
            const fileItem = document.createElement('div');
            fileItem.className = 'list-group-item d-flex justify-content-between align-items-center py-2';

            const fileInfo = document.createElement('div');
            fileInfo.className = 'd-flex align-items-center';

            const fileIcon = document.createElement('i');
            // Different icon based on file type
            if (file.type.includes('pdf')) {
                fileIcon.className = 'fa fa-file-pdf me-2 text-danger';
            } else if (file.type.includes('image')) {
                fileIcon.className = 'fa fa-file-image me-2 text-primary';
            } else {
                fileIcon.className = 'fa fa-file me-2';
            }

            const fileName = document.createElement('span');
            fileName.textContent = file.name;
            fileName.className = 'me-2';

            const fileSize = document.createElement('small');
            fileSize.textContent = `(${formatFileSize(file.size)})`;
            fileSize.className = 'text-muted';

            fileInfo.appendChild(fileIcon);
            fileInfo.appendChild(fileName);
            fileInfo.appendChild(fileSize);

            const removeBtn = document.createElement('button');
            removeBtn.type = 'button';
            removeBtn.className = 'btn btn-sm btn-danger';
            removeBtn.innerHTML = '';
            removeBtn.onclick = function() {
                removeReceipt(index);
            };

            fileItem.appendChild(fileInfo);
            fileItem.appendChild(removeBtn);
            listGroup.appendChild(fileItem);
        });

        receiptsList.appendChild(listGroup);
    }

    function removeReceipt(index) {
        selectedReceipts.splice(index, 1);
        renderReceiptsList();
    }

    function formatFileSize(bytes) {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
    }

    // On form submit, append files to FormData
    form.addEventListener('submit', function(e) {
        // Remove any existing file inputs with name 'receipts'
        const existingInputs = form.querySelectorAll('input[name="receipts"]');
        existingInputs.forEach(input => input.remove());

        // Add selected receipts to form
        selectedReceipts.forEach((file, index) => {
            const fileInputHidden = document.createElement('input');
            fileInputHidden.type = 'file';
            fileInputHidden.name = 'receipts';
            fileInputHidden.style.display = 'none';

            // Create a DataTransfer object to assign the file
            const dataTransfer = new DataTransfer();
            dataTransfer.items.add(file);
            fileInputHidden.files = dataTransfer.files;

            form.appendChild(fileInputHidden);
        });
    });
});

